def russian_message_word(number: int) -> str:
    number = abs(number)
    if number % 100 in range(11, 15):
        return "сообщений"
    if number % 10 == 1:
        return "сообщение"
    if number % 10 in range(2, 5):
        return "сообщения"
    return "сообщений"


